command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-name-index --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "6e6e1a66cf69c7158f2bfa2be329341b72d5b388") { throw "main moved" }
if ((git rev-parse origin/work/large-folder-name-index).Trim() -ne "58f0d2814c90026984f27d9ec2604fdb6babdea2") { throw "candidate branch moved" }
if ((git status --short).Count -ne 0) { throw "dirty persistent checkout" }
git checkout -B work/large-folder-name-index origin/work/large-folder-name-index
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
if ((git rev-parse HEAD).Trim() -ne "58f0d2814c90026984f27d9ec2604fdb6babdea2") { throw "candidate mismatch" }
python -X utf8 -m py_compile tests\winui\test_m22_contract.py tests\winui\test_large_owned_folder_gui.py
if ($LASTEXITCODE -ne 0) { throw "changed Python syntax failed" }
cmd /c test.bat source
if ($LASTEXITCODE -ne 0) { throw "source contracts failed" }
cmd /c build.bat Release
if ($LASTEXITCODE -ne 0) { throw "Release build failed" }
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 2300 --configuration Release
if ($LASTEXITCODE -ne 0) { throw "2300-item filter shortcut GUI smoke failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_NAME_FILTER_SHORTCUT_SMOKE_PASS"
